//! Contract fixtures shared by unit tests and integration suites.
//! Single source of truth: every test references these constants, never
//! an inline copy. Values are base64-encoded contract sources (the same
//! encoding governance events carry).

/// Basic three-counter contract: ModThree=50 is rejected.
pub const EXAMPLE_CONTRACT: &str = "";

/// Truncated base64: fails decoding before any compilation happens.
pub const INVALID_EXAMPLE_CONTRACT: &str = "dXNlIHNlcmRlOjp7U2VyaWFsaXp";

/// EXAMPLE_CONTRACT with an infinite loop in ModOne: exhausts fuel.
pub const FUEL_EXHAUSTING_CONTRACT: &str = "";

/// String-state contract (ChangeData event): a different schema shape.
pub const CHANGED_SCHEMA_CONTRACT: &str = "";

/// Same logic as EXAMPLE_CONTRACT but without the ModThree=50 rejection:
/// tells apart which contract version a node evaluated.
pub const EXAMPLE_CONTRACT_V2: &str = "";
